css:
.ccm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.ccm-root,.ccm-root *,.ccm-root *::before,.ccm-root *::after{box-sizing:border-box}
.ccm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.ccm-root img{display:block;border:0;max-width:none}
.ccm-root > [data-node-id]{will-change:transform}
.ccm-root [hidden]{display:none!important}
.ccm-root [data-sh-theme="dark"]{display:none!important}
.ccm-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.ccm-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.ccm-root .n427_5215{align-content:stretch;display:flex;gap:4px;height:27px;align-items:center;position:relative;flex-shrink:0;width:100%}
.ccm-root .n427_5216{align-content:stretch;display:flex;gap:10px;align-items:center;padding:2px;position:relative;border-radius:9px;flex-shrink:0;width:25px;height:25px}
.ccm-root .n427_5222{overflow:clip;position:relative;flex-shrink:0;width:18px;height:18px}
.ccm-root .x24{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.ccm-root .n427_5235{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:620;line-height:24px;font-style:normal;position:relative;flex-shrink:0;font-size:20px;color:var(--wa-text, #000);white-space:nowrap;width:70px}
.ccm-root [data-node-id="427:1289"],.ccm-root [data-node-id="427:1317"]{height:auto!important}
.ccm-root [data-node-id="427:1537"]{width:100%!important}
.ccm-root [data-name^="Card/Stage"] p{letter-spacing:-0.05em;word-break:keep-all}
.ccm-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.ccm-root[data-theme="dark"] > [data-node-id]{background:linear-gradient(180deg,var(--wa-bg, #111720) 0%,var(--wa-bg, #0b0e13) 100%)!important}
.ccm-root[data-theme="dark"] [data-name="3D Scene"] img{filter:brightness(.88) saturate(.95) contrast(1.04)}
.ccm-root[data-theme="dark"] [data-name="Diagram Title Patch"]{background:linear-gradient(90deg,var(--wa-point, #3d2f63) 0%,var(--wa-point, #1b2a38) 50%,var(--wa-point, #352c5d) 100%)!important;border-color:var(--wa-point, #7d7bf0)!important}
.ccm-root[data-theme="dark"] [data-name="Diagram Title Patch"] p{color:var(--wa-text, #eef0fb)!important}
.ccm-root[data-theme="dark"] [data-name="Side Rail"] > [data-name="Body"]{background:linear-gradient(180deg,var(--wa-surface, #151920) 47%,color-mix(in srgb, var(--wa-surface, rgb(21 25 32)) 90%, transparent) 100%)!important;border-right-color:color-mix(in srgb, var(--wa-line, rgb(255 255 255)) 6%, transparent)!important}
.ccm-root[data-theme="dark"] [data-name^="Panel/"]:not([data-name="Panel/File Open"]),.ccm-root[data-theme="dark"] [data-name="Popup/Detail"]{box-shadow:inset 1px 0 0 rgba(255,255,255,.04),0 12px 30px rgba(0,0,0,.35)}
.ccm-root[data-theme="dark"] [data-name="Icon Button"]{box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}
.ccm-root[data-theme="dark"] .n427_5235{color:var(--wa-text, #eceef2)}
